[
  {
    "id": "must_take_cart",
    "text": "The shopper is obliged to obtain a cart at some point during the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "must_end_with_cart",
    "text": "The shopper is prohibited from exiting the store without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_at_item",
    "text": "The shopper is prohibited from being at the item location while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_collect_item_with_cart",
    "text": "The shopper is prohibited from interacting with the item location while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_being_without",
    "text": "Whenever the shopper is without a cart, they are obliged to later have a cart again.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "not": "hasCart"
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "park_cart_at_aisle_entry",
    "text": "When the shopper reaches cell (3,3) with a cart, they are obliged to interact there.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          "hasCart"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "no_cart_north_from_aisle_entry",
    "text": "The shopper is prohibited from moving north from cell (3,3) while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_at_aisle_entry",
    "text": "When the shopper is at cell (3,3) without a cart, they are obliged to interact there eventually.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "INTERACT"
        ]
      }
    }
  }
]
